package com.yeyamo_mobile.api.feed_service.infrastructure.persistence;
import java.time.Instant;
import java.util.UUID;
import jakarta.persistence.*;
@Entity@Table(name="feed_posts")public class FeedPostEntity{@Id private UUID postId;@Column(name="author_id",nullable=false,length=120)private String authorId;@Column(columnDefinition="TEXT")private String caption;@Column(nullable=false,length=20)private String visibility;@Column(nullable=false,length=20)private String status;@Column(name="catalog_asset_id")private UUID catalogAssetId;@Column(name="media_ids",nullable=false,columnDefinition="TEXT")private String mediaIds;@Column(nullable=false,columnDefinition="TEXT")private String hashtags;@Column(nullable=false)private boolean available;@Column(name="published_at")private Instant publishedAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;public UUID getPostId(){return postId;}public void setPostId(UUID v){postId=v;}public String getAuthorId(){return authorId;}public void setAuthorId(String v){authorId=v;}public String getCaption(){return caption;}public void setCaption(String v){caption=v;}public String getVisibility(){return visibility;}public void setVisibility(String v){visibility=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public UUID getCatalogAssetId(){return catalogAssetId;}public void setCatalogAssetId(UUID v){catalogAssetId=v;}public String getMediaIds(){return mediaIds;}public void setMediaIds(String v){mediaIds=v;}public String getHashtags(){return hashtags;}public void setHashtags(String v){hashtags=v;}public boolean isAvailable(){return available;}public void setAvailable(boolean v){available=v;}public Instant getPublishedAt(){return publishedAt;}public void setPublishedAt(Instant v){publishedAt=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}public long getVersion(){return version;}public void setVersion(long v){version=v;}}
